import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const l=JSON.parse('{"title":"Keynote- Opening Remarks - Enrica Porcari & Jakub Mościcki, CERN","description":"","frontmatter":{"title":"Keynote- Opening Remarks - Enrica Porcari & Jakub Mościcki, CERN","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","CERN","开源技术","会议"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Opening_Remarks_-_Enrica_Porcari_Jakub_Mo_cicki_CERN.md","filePath":"posts/2025/Keynote_-_Opening_Remarks_-_Enrica_Porcari_Jakub_Mo_cicki_CERN.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Keynote_-_Opening_Remarks_-_Enrica_Porcari_Jakub_Mo_cicki_CERN.md"};function o(h,e,p,c,_,s){return r(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="ceph-2024-大会开幕致辞会议纪要" tabindex="-1">Ceph 2024 大会开幕致辞会议纪要 <a class="header-anchor" href="#ceph-2024-大会开幕致辞会议纪要" aria-label="Permalink to &quot;Ceph 2024 大会开幕致辞会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 2024年<br><strong>会议地点</strong>: CERN（欧洲核子研究组织）<br><strong>主持人</strong>:</p><ul><li><strong>Fabio Giannuzzi</strong>（CERN IT 部门负责人）</li><li><strong>Kuba Mracek</strong>（CERN 存储与数据管理组负责人）</li></ul><h4 id="会议背景与目的" tabindex="-1">会议背景与目的 <a class="header-anchor" href="#会议背景与目的" aria-label="Permalink to &quot;会议背景与目的&quot;">​</a></h4><p>Ceph 是一个开源分布式存储系统，正在改变存储方式。本次大会旨在汇聚全球 Ceph 社区成员，共同应对未来存储挑战，推动技术创新与合作，并庆祝社区的持续贡献与合作精神。</p><h4 id="cern-的角色与贡献" tabindex="-1">CERN 的角色与贡献 <a class="header-anchor" href="#cern-的角色与贡献" aria-label="Permalink to &quot;CERN 的角色与贡献&quot;">​</a></h4><p>CERN 作为开放科学和开源技术的引领者，也是 Ceph 的重要用户和贡献者。自 2013 年开始使用 Ceph，现已将其作为数据中心基础设施的核心组成部分。CERN 的 Ceph 基础设施规模庞大，支持多种高可用性和灾难恢复策略，并与 Ceph 开发团队紧密合作，推动技术的扩展和优化。</p><h4 id="cern-的存储需求与挑战" tabindex="-1">CERN 的存储需求与挑战 <a class="header-anchor" href="#cern-的存储需求与挑战" aria-label="Permalink to &quot;CERN 的存储需求与挑战&quot;">​</a></h4><p>CERN 的实验和模拟生成了大量数据，存储需求持续增长。CERN 的存储系统包括磁带和磁盘存储，总容量达到 2.5 艾字节，由 CERN 开发的开放源存储系统管理。</p><h4 id="ceph-在-cern-的应用" tabindex="-1">Ceph 在 CERN 的应用 <a class="header-anchor" href="#ceph-在-cern-的应用" aria-label="Permalink to &quot;Ceph 在 CERN 的应用&quot;">​</a></h4><p>Ceph 已成为 CERN 数据中心数百个服务的基础，支持块存储、对象存储和文件系统存储。CERN 的 Ceph 基础设施具有高复杂性和大规模，经常遇到其他用户未来可能面临的问题，因此 CERN 乐于分享其操作经验和解决方案。</p><h4 id="社区合作与贡献" tabindex="-1">社区合作与贡献 <a class="header-anchor" href="#社区合作与贡献" aria-label="Permalink to &quot;社区合作与贡献&quot;">​</a></h4><p>CERN 与 Ceph 社区保持紧密合作，通过大规模测试推动了 Ceph 技术的发展。CERN 希望通过分享其操作经验和问题解决方案，继续为 Ceph 技术的进步和社区的发展做出贡献。</p><h4 id="会议组织与感谢" tabindex="-1">会议组织与感谢 <a class="header-anchor" href="#会议组织与感谢" aria-label="Permalink to &quot;会议组织与感谢&quot;">​</a></h4><p>本次大会由 CERN 的存储与数据管理组和 Linux 基金会共同主办，感谢 Ceph 基金会、Linux 基金会以及 CERN 团队的辛勤工作，确保了大会的顺利进行。</p><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><p>会议将继续深入讨论 Ceph 的技术发展、应用场景以及社区合作，推动 Ceph 在更多领域的应用和优化。与会者将有机会通过互动和交流，结识新朋友，激发创新思维，共同应对未来的存储挑战。</p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>本次 Ceph 2024 大会是对 Ceph 社区过去贡献的庆祝，更是对未来挑战的展望。CERN 作为 Ceph 的重要用户和贡献者，将继续通过大规模测试和经验分享，推动 Ceph 技术的发展。会议的成功举办得益于 CERN 和 Linux 基金会的合作，以及全球 Ceph 社区的积极参与。</p>',19)])])}const d=a(n,[["render",o]]);export{l as __pageData,d as default};
